require_once 'header.php';
function createSlug($str){$u=['a'=>'á|à|ả|ã|ạ|ă|ắ|ặ|ằ|ẳ|ẵ|â|ấ|ầ|ẩ|ẫ|ậ','d'=>'đ','e'=>'é|è|ẻ|ẽ|ẹ|ê|ế|ề|ể|ễ|ệ','i'=>'í|ì|ỉ|ĩ|ị','o'=>'ó|ò|ỏ|õ|ọ|ô|ố|ồ|ổ|ỗ|ộ|ơ|ớ|ờ|ở|ỡ|ợ','u'=>'ú|ù|ủ|ũ|ụ|ư|ứ|ừ|ử|ữ|ự','y'=>'ý|ỳ|ỷ|ỹ|ỵ'];foreach($u as $n=>$v)$str=preg_replace("/($v)/i",$n,$str);$str=strtolower($str);$str=preg_replace('/[^a-z0-9\-]/','-',$str);return trim(preg_replace('/-+/','-',$str),'-');}
$search=trim($_GET['search']??'');$cat_ids=array_values(array_filter(array_map('intval',(array)($_GET['categories']??[]))));$brand_ids=array_values(array_filter(array_map('intval',(array)($_GET['brands']??[]))));$feature=trim($_GET['platform']??'');$min_price=max(0,(float)($_GET['min_price']??0));$max_price=max(0,(float)($_GET['max_price']??0));$sort=$_GET['sort']??'newest';$page=max(1,(int)($_GET['page']??1));$limit=12;
$where=['1=1'];$params=[];$types='';
if($search!==''){$where[]='p.name LIKE ?';$params[]='%'.$search.'%';$types.='s';}
if($cat_ids)$where[]='p.category_id IN ('.implode(',',$cat_ids).')';
if($brand_ids)$where[]='p.brand_id IN ('.implode(',',$brand_ids).')';
if($feature!==''){$where[]='p.warranty_text LIKE ?';$params[]='%'.$feature.'%';$types.='s';}
if($min_price>0){$where[]='(CASE WHEN p.sale_price>0 THEN p.sale_price ELSE p.price END)>=?';$params[]=$min_price;$types.='d';}
if($max_price>0){$where[]='(CASE WHEN p.sale_price>0 THEN p.sale_price ELSE p.price END)<=?';$params[]=$max_price;$types.='d';}
$order=['newest'=>'p.id DESC','popular'=>'p.sales_count DESC','price_asc'=>'(CASE WHEN p.sale_price>0 THEN p.sale_price ELSE p.price END) ASC','price_desc'=>'(CASE WHEN p.sale_price>0 THEN p.sale_price ELSE p.price END) DESC'][$sort]??'p.id DESC';$where_sql=implode(' AND ',$where);
$count=$conn->prepare("SELECT COUNT(*) c FROM products p WHERE $where_sql");if($params)$count->bind_param($types,...$params);$count->execute();$total_rows=(int)$count->get_result()->fetch_assoc()['c'];$count->close();
$total_pages=max(1,(int)ceil($total_rows/$limit));$page=min($page,$total_pages);$offset=($page-1)*$limit;$sql="SELECT p.*,c.name category_name,b.name brand_name FROM products p LEFT JOIN categories c ON p.category_id=c.id LEFT JOIN brands b ON p.brand_id=b.id WHERE $where_sql ORDER BY $order LIMIT $limit OFFSET $offset";$stmt=$conn->prepare($sql);if($params)$stmt->bind_param($types,...$params);$stmt->execute();$products=$stmt->get_result();
$categories=[];$q=$conn->query("SELECT * FROM categories WHERE status=1 ORDER BY id");while($r=$q->fetch_assoc())$categories[]=$r;$brands=[];$q=$conn->query("SELECT * FROM brands WHERE status=1 ORDER BY name");while($r=$q->fetch_assoc())$brands[]=$r;$features=['16GB','5G','USB-C','Wi-Fi 6','OLED','180Hz','Bluetooth','NVMe'];
function query_page($page){$q=$_GET;$q['page']=$page;return '?'.http_build_query($q);}
