;color:var(--primary-dark)}.stock-badge.low{color:#c2410c;background:#fff7ed}.shop-info{padding:12px}.shop-meta{display:flex;align-items:center;justify-content:space-between;gap:7px;color:var(--muted);font-size:12px}.shop-meta strong{color:var(--primary)}.shop-name{height:42px;margin:6px 0;color:var(--navy);font-size:15px;line-height:1.35;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.feature-line{height:31px;padding:0 8px;border-radius:7px;background:var(--soft);color:#53657e;font-size:12px;display:flex;align-items:center;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.shop-bottom{margin-top:9px;display:flex;align-items:flex-end;justify-content:space-between;gap:8px}.shop-price strong{display:block;color:#e11d48;font-size:17px}.shop-price del{font-size:12px;color:#9ca7b6}.shop-view{width:32px;height:32px;border-radius:8px;background:var(--primary);color:#fff;display:flex;align-items:center;justify-content:center}.empty-state{grid-column:1/-1;padding:56px 20px;text-align:center;border:1px solid var(--line);border-radius:12px;background:#fff;color:var(--muted)}.empty-state i{font-size:30px;color:var(--primary);margin-bottom:8px}@media(max-width:1050px){.shop-layout{grid-template-columns:220px 1fr}.shop-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:780px){.shop-layout{grid-template-columns:1fr}.filter-sidebar{position:static}.filter-title button{display:block;border:0;background:transparent;color:var(--navy)}.filter-body{display:none}.filter-sidebar.open .filter-body{display:block}.shop-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:520px){.shop-head{align-items:flex-start}.shop-count{min-width:84px}.shop-grid{grid-template-columns:1fr 1fr}.shop-image{height:145px}.shop-name{font-size:14px}}
</style>
